function validate([s, repeatLimit]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may only contain lowercase letters.';
  if (!Number.isInteger(repeatLimit) || repeatLimit < 1 || repeatLimit > s.length) return 'repeatLimit is between 1 and the length of s.';
  return null;
}

