function repeatLimitedString(s, repeatLimit) {
  const count = new Array(26).fill(0);
  for (const ch of s) {
    count[ch.charCodeAt(0) - 97]++;
  }

  const parts = [];
  let top = 25;
  while (top >= 0) {
    if (count[top] === 0) {
      top--;
      continue;
    }
    const take = Math.min(count[top], repeatLimit);
    parts.push(String.fromCharCode(97 + top).repeat(take));
    count[top] -= take;
    if (count[top] === 0) {
      continue;
    }
    let next = top - 1;
    while (next >= 0 && count[next] === 0) {
      next--;
    }
    if (next < 0) {
      break;
    }
    parts.push(String.fromCharCode(97 + next));
    count[next]--;
  }
  return parts.join('');
}

