function repeatLimitedString(s, repeatLimit) {
  // Any letter that may legally come next leads to a valid string, so the greatest
  // answer always places the largest such letter; build it one character at a time.
  const left = new Map();
  for (const ch of s) left.set(ch, (left.get(ch) || 0) + 1);
  const letters = [...left.keys()].sort().reverse();
  let out = '';
  for (;;) {
    const run = out.length >= repeatLimit && out.slice(-repeatLimit).split('').every(c => c === out[out.length - 1]);
    const pick = letters.find(ch => left.get(ch) > 0 && !(run && ch === out[out.length - 1]));
    if (pick === undefined) return out;
    out += pick;
    left.set(pick, left.get(pick) - 1);
  }
}

