function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 7);
  const kinds = size === 'large' ? 1 + Math.floor(rand() * 26) : 1 + Math.floor(rand() * 4);
  const pool = [];
  while (pool.length < kinds) {
    const ch = String.fromCharCode(97 + Math.floor(rand() * 26));
    if (!pool.includes(ch)) pool.push(ch);
  }
  pool.sort().reverse();
  // Skew toward the largest letters so the repeat limit actually binds.
  const skew = 1 + rand() * 4;
  let s = '';
  for (let i = 0; i < n; i++) {
    s += pool[Math.floor(Math.pow(rand(), skew) * pool.length)];
  }
  const limitCap = size === 'large' && rand() < 0.7 ? Math.min(n, 5) : n;
  const repeatLimit = 1 + Math.floor(rand() * limitCap);
  return [s, repeatLimit];
}
